DELETE FROM dashboard_metrics a USING dashboard_metrics b
      WHERE a.ctid < b.ctid
        AND a."tenantId" = b."tenantId"
        AND a.metric_key = b.metric_key
        AND a.period IS NOT DISTINCT FROM b.period;
