-- 1730000700000-CampaignExecutionRedesign.ts  (42 statements)
-- ─────────────────────────────────────────────────────────────────────────

CREATE TYPE "public"."campaigns_lifecycle_enum" AS ENUM('DRAFT','SCHEDULED','ACTIVE','PAUSED','ARCHIVED');
CREATE TYPE "public"."campaign_runs_execution_enum" AS ENUM('IDLE','ENQUEUEING','PROCESSING','DRAINING','COMPLETED','FAILED');
CREATE TYPE "public"."campaign_recipients_processing_enum" AS ENUM('PENDING','DISPATCHING','DISPATCHED','FAILED','SKIPPED');
CREATE TYPE "public"."campaign_recipients_delivery_enum" AS ENUM('NONE','ACCEPTED','DELIVERED','READ','BOUNCED');
CREATE TYPE "public"."campaign_recipients_failure_class_enum" AS ENUM('TRANSIENT','PERMANENT');
CREATE TYPE "public"."outbox_jobs_status_enum" AS ENUM('PENDING','PUBLISHED','FAILED');
ALTER TABLE "campaigns" ADD COLUMN "lifecycle" "public"."campaigns_lifecycle_enum" NOT NULL DEFAULT 'DRAFT';
UPDATE "campaigns" SET "lifecycle" = CASE "status"
        WHEN 'DRAFT' THEN 'DRAFT'
        WHEN 'SCHEDULED' THEN 'SCHEDULED'
        WHEN 'RUNNING' THEN 'ACTIVE'
        WHEN 'PAUSED' THEN 'PAUSED'
        WHEN 'COMPLETED' THEN 'ARCHIVED'
        WHEN 'CANCELLED' THEN 'ARCHIVED'
        ELSE 'DRAFT' END::"public"."campaigns_lifecycle_enum";
DROP INDEX IF EXISTS "public"."IDX_07da9db483388fb0565e8b5fa3";
CREATE INDEX "IDX_campaigns_tenant_lifecycle" ON "campaigns" ("tenantId", "lifecycle");
ALTER TABLE "campaigns" DROP COLUMN "status";
DROP TYPE IF EXISTS "public"."campaigns_status_enum";
CREATE TABLE "campaign_runs" (
        "id" uuid NOT NULL DEFAULT uuid_generate_v4(),
        "execution" "public"."campaign_runs_execution_enum" NOT NULL DEFAULT 'IDLE',
        "total_recipients" integer NOT NULL DEFAULT 0,
        "queued" integer NOT NULL DEFAULT 0,
        "sent" integer NOT NULL DEFAULT 0,
        "delivered" integer NOT NULL DEFAULT 0,
        "read" integer NOT NULL DEFAULT 0,
        "failed" integer NOT NULL DEFAULT 0,
        "skipped" integer NOT NULL DEFAULT 0,
        "idempotency_key" uuid NOT NULL,
        "version" integer NOT NULL,
        "started_at" TIMESTAMP WITH TIME ZONE,
        "finished_at" TIMESTAMP WITH TIME ZONE,
        "created_at" TIMESTAMP NOT NULL DEFAULT now(),
        "updated_at" TIMESTAMP DEFAULT now(),
        "tenantId" uuid,
        "campaignId" uuid,
        CONSTRAINT "PK_campaign_runs" PRIMARY KEY ("id")
      );
CREATE INDEX "IDX_campaign_runs_tenant_campaign_created" ON "campaign_runs" ("tenantId", "campaignId", "created_at");
CREATE INDEX "IDX_campaign_runs_execution" ON "campaign_runs" ("execution");
ALTER TABLE "campaign_runs" ADD CONSTRAINT "FK_campaign_runs_tenant" FOREIGN KEY ("tenantId") REFERENCES "tenants"("id") ON DELETE NO ACTION ON UPDATE NO ACTION;
ALTER TABLE "campaign_runs" ADD CONSTRAINT "FK_campaign_runs_campaign" FOREIGN KEY ("campaignId") REFERENCES "campaigns"("id") ON DELETE CASCADE ON UPDATE NO ACTION;
INSERT INTO "campaign_runs" ("id","execution","idempotency_key","version","tenantId","campaignId","started_at","finished_at")
      SELECT uuid_generate_v4(), 'COMPLETED', uuid_generate_v4(), 1, c."tenantId", c."id", now(), now()
      FROM "campaigns" c
      WHERE EXISTS (SELECT 1 FROM "campaign_recipients" r WHERE r."campaignId" = c."id");
ALTER TABLE "campaign_recipients" ADD COLUMN "runId" uuid;
ALTER TABLE "campaign_recipients" ADD COLUMN "processing" "public"."campaign_recipients_processing_enum" NOT NULL DEFAULT 'PENDING';
ALTER TABLE "campaign_recipients" ADD COLUMN "delivery" "public"."campaign_recipients_delivery_enum" NOT NULL DEFAULT 'NONE';
ALTER TABLE "campaign_recipients" ADD COLUMN "provider_ref" character varying(255);
ALTER TABLE "campaign_recipients" ADD COLUMN "failure_class" "public"."campaign_recipients_failure_class_enum";
ALTER TABLE "campaign_recipients" ADD COLUMN "failure_reason" text;
ALTER TABLE "campaign_recipients" ADD COLUMN "attempts" integer NOT NULL DEFAULT 0;
ALTER TABLE "campaign_recipients" ADD COLUMN "dispatched_at" TIMESTAMP WITH TIME ZONE;
ALTER TABLE "campaign_recipients" ADD COLUMN "delivered_at" TIMESTAMP WITH TIME ZONE;
UPDATE "campaign_recipients" SET
        "processing" = CASE "status"
          WHEN 'QUEUED' THEN 'PENDING'
          WHEN 'SENT' THEN 'DISPATCHED'
          WHEN 'DELIVERED' THEN 'DISPATCHED'
          WHEN 'READ' THEN 'DISPATCHED'
          WHEN 'FAILED' THEN 'FAILED'
          WHEN 'SKIPPED' THEN 'SKIPPED'
          ELSE 'PENDING' END::"public"."campaign_recipients_processing_enum",
        "delivery" = CASE "status"
          WHEN 'DELIVERED' THEN 'DELIVERED'
          WHEN 'READ' THEN 'READ'
          ELSE 'NONE' END::"public"."campaign_recipients_delivery_enum",
        "dispatched_at" = "sent_at";
UPDATE "campaign_recipients" r
      SET "runId" = (SELECT cr."id" FROM "campaign_runs" cr WHERE cr."campaignId" = r."campaignId" ORDER BY cr."created_at" ASC LIMIT 1)
      WHERE r."runId" IS NULL;
UPDATE "campaign_runs" cr SET
        "total_recipients" = sub.total,
        "sent" = sub.sent, "failed" = sub.failed, "skipped" = sub.skipped,
        "delivered" = sub.delivered, "read" = sub.read,
        "queued" = sub.pending
      FROM (
        SELECT "runId",
          COUNT(*) AS total,
          COUNT(*) FILTER (WHERE "processing" = 'DISPATCHED') AS sent,
          COUNT(*) FILTER (WHERE "processing" = 'FAILED') AS failed,
          COUNT(*) FILTER (WHERE "processing" = 'SKIPPED') AS skipped,
          COUNT(*) FILTER (WHERE "processing" = 'PENDING') AS pending,
          COUNT(*) FILTER (WHERE "delivery" = 'DELIVERED') AS delivered,
          COUNT(*) FILTER (WHERE "delivery" = 'READ') AS read
        FROM "campaign_recipients" GROUP BY "runId"
      ) sub
      WHERE cr."id" = sub."runId";
CREATE UNIQUE INDEX "UQ_campaign_recipients_provider_ref" ON "campaign_recipients" ("provider_ref") WHERE "provider_ref" IS NOT NULL;
ALTER TABLE "campaign_recipients" ADD CONSTRAINT "FK_campaign_recipients_run" FOREIGN KEY ("runId") REFERENCES "campaign_runs"("id") ON DELETE CASCADE ON UPDATE NO ACTION;
DROP INDEX IF EXISTS "public"."IDX_3f28c2b1ce5590ea0892267033";
ALTER TABLE "campaign_recipients" DROP CONSTRAINT IF EXISTS "UQ_60e8fbccdf8ccd204d395156be7";
CREATE UNIQUE INDEX "uq_recipient_run_customer" ON "campaign_recipients" ("runId", "customerId");
CREATE INDEX "ix_recipient_run_processing" ON "campaign_recipients" ("runId", "processing");
CREATE INDEX "ix_recipient_campaign_customer" ON "campaign_recipients" ("campaignId", "customerId");
ALTER TABLE "campaign_recipients" DROP COLUMN "status";
ALTER TABLE "campaign_recipients" DROP COLUMN "sent_at";
