CREATE EXTENSION IF NOT EXISTS btree_gist;
ALTER TABLE "appointments"
      ADD CONSTRAINT "appointments_no_overlap"
      EXCLUDE USING gist (
        "staffId" WITH =,
        tstzrange("start_at", "end_at", '[)') WITH &&
      )
      WHERE (status NOT IN ('CANCELLED','NO_SHOW') AND deleted_at IS NULL);

